using namespace MCFM;

std::vector<int> MCFM::ID(size_t id)
{
  std::vector<int> ids;
  for (size_t n(0);id>0;++n) {
    if (id&(1<<n)) {
      ids.push_back(n);
      id-=1<<n;
    }
  }
  return ids;
}

size_t MCFM::ID(const std::vector<int> &id)
{
  size_t ids(0);
  for (size_t n(0);n<id.size();++n) ids|=1<<n;
  return ids;
}

